def conv_transpose1d_batch(self, kernel, batch, channels, filters,
                           length, size, stride=1, padding=0,
                           dilation=1):
    if not isinstance(kernel, Tensor):
        raise TypeError("kernel must be a Tensor")
    # The operands must hold non-empty 1D finite float lists; data may
    # have been mutated after construction, so re-validate at call time.
    x_data = _require_nonempty_float_vector(
        self, "conv_transpose1d_batch"
    )
    w_data = _require_nonempty_float_vector(
        kernel, "conv_transpose1d_batch"
    )
    # batch, channels, filters, length, size, stride and dilation must
    # be non-bool positive ints, and padding a non-bool non-negative int.
    for name, value in (
        ("batch", batch),
        ("channels", channels),
        ("filters", filters),
        ("length", length),
        ("size", size),
        ("stride", stride),
        ("dilation", dilation),
    ):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(name + " must be a positive int")
        if value <= 0:
            raise ValueError(name + " must be a positive int")
    if isinstance(padding, bool) or not isinstance(padding, int):
        raise TypeError("padding must be a non-negative int")
    if padding < 0:
        raise ValueError("padding must be a non-negative int")
    B, C, O, N, K, S, P, D = (
        batch, channels, filters, length, size, stride, padding,
        dilation,
    )
    # self stores B sequences of C channels of N samples and kernel O
    # filters of C channels of K weights, all in row-major order.
    if len(x_data) != B * C * N:
        raise ValueError(
            "conv_transpose1d_batch input length must equal "
            "batch * channels * length"
        )
    if len(w_data) != C * O * K:
        raise ValueError(
            "conv_transpose1d_batch kernel length must equal "
            "channels * filters * size"
        )
    # A transposed convolution scatters each input sample onto the
    # output through the (unflipped) dilated kernel, trimmed by padding.
    L = (N - 1) * S - 2 * P + D * (K - 1) + 1
    if L <= 0:
        raise ValueError(
            "conv_transpose1d_batch output length must be positive"
        )
    # Snapshot both operands at call time so later caller-side mutation
    # or replacement of either input can change neither the forward
    # result nor a pending backward pass.
    snapshot_x = list(x_data)
    snapshot_w = list(w_data)
    # Batched multi-channel 1D transposed cross-correlation: the kernel
    # is never flipped. In ascending (b, c, i, o, r) order, each input
    # sample scatters y[(b*O+o)*L+t] += x[(b*C+c)*N+i] * w[(c*O+o)*K+r]
    # with t = i*S-P+r*D; out-of-range output positions from padding or
    # the dilation gaps are skipped. The output layout is B x O x L in
    # row-major order. A non-finite product or partial sum aborts before
    # a result tensor exists, so no state can change.
    out_len = B * O * L
    out_data = [0.0] * out_len
    for b in range(B):
        for c in range(C):
            for i in range(N):
                xi = (b * C + c) * N + i
                xval = snapshot_x[xi]
                for o in range(O):
                    wi_base = (c * O + o) * K
                    oi_base = (b * O + o) * L
                    for r in range(K):
                        t = i * S - P + r * D
                        if not 0 <= t < L:
                            continue
                        product = xval * snapshot_w[wi_base + r]
                        if not math.isfinite(product):
                            raise ValueError(
                                "conv_transpose1d_batch intermediate "
                                "must be finite"
                            )
                        oi = oi_base + t
                        out_data[oi] = out_data[oi] + product
                        if not math.isfinite(out_data[oi]):
                            raise ValueError(
                                "conv_transpose1d_batch intermediate "
                                "must be finite"
                            )
    if not (self.requires_grad or kernel.requires_grad):
        return Tensor._make(
            out_data, False, (), None,
            grad_validator=lambda g: _validate_vector_grad(g, out_len),
        )
    parent_self, parent_kernel = self, kernel

    def backward_fn(grad):
        # dx[xi] += g*w[wi] and dw[wi] += g*x[xi], accumulated from
        # 0.0 in the same ascending (b, c, i, o, r) order, indexing and
        # t computation as the forward pass, with the same out-of-range
        # skip; dw has no batch index, so its contributions reduce
        # across all B images. A non-finite product or partial sum
        # aborts the whole pass before any grad is written.
        dx = [0.0] * (B * C * N)
        dw = [0.0] * (C * O * K)
        for b in range(B):
            for c in range(C):
                for i in range(N):
                    xi = (b * C + c) * N + i
                    xval = snapshot_x[xi]
                    for o in range(O):
                        wi_base = (c * O + o) * K
                        oi_base = (b * O + o) * L
                        for r in range(K):
                            t = i * S - P + r * D
                            if not 0 <= t < L:
                                continue
                            wi = wi_base + r
                            gv = grad[oi_base + t]
                            contrib_x = gv * snapshot_w[wi]
                            if not math.isfinite(contrib_x):
                                raise ValueError(
                                    "conv_transpose1d_batch backward "
                                    "intermediate must be finite"
                                )
                            dx[xi] = dx[xi] + contrib_x
                            if not math.isfinite(dx[xi]):
                                raise ValueError(
                                    "conv_transpose1d_batch backward "
                                    "intermediate must be finite"
                                )
                            contrib_w = gv * xval
                            if not math.isfinite(contrib_w):
                                raise ValueError(
                                    "conv_transpose1d_batch backward "
                                    "intermediate must be finite"
                                )
                            dw[wi] = dw[wi] + contrib_w
                            if not math.isfinite(dw[wi]):
                                raise ValueError(
                                    "conv_transpose1d_batch backward "
                                    "intermediate must be finite"
                                )
        # The same object may play both roles; merge such roles into
        # one contribution per tensor, and submit only parents that
        # require grad.
        merged = {}
        roles = (
            (parent_self, dx),
            (parent_kernel, dw),
        )
        for parent, value in roles:
            if not parent.requires_grad:
                continue
            entry = merged.get(id(parent))
            if entry is None:
                merged[id(parent)] = [parent, value]
            else:
                combined = _merge_grad(entry[1], value)
                _ensure_finite_grad(combined)
                entry[1] = combined
        return [(entry[0], entry[1]) for entry in merged.values()]

    return Tensor._make(
        out_data, True, (parent_self, parent_kernel), backward_fn,
        grad_validator=lambda g: _validate_vector_grad(g, out_len),
    )

def conv2d(self, kernel, height, width, kernel_size, stride=1,
           padding=0, dilation=1):
    if not isinstance(kernel, Tensor):
        raise TypeError("kernel must be a Tensor")
    # Both operands must hold non-empty 1D finite float lists; data may
    # have been mutated after construction, so re-validate at call time.
    x_data = _require_nonempty_float_vector(self, "conv2d")
    k_data = _require_nonempty_float_vector(kernel, "conv2d")
    # H, W, kernel_size, stride and dilation must be non-bool positive
    # ints, and padding a non-bool non-negative int.
    for name, value in (
        ("height", height),
        ("width", width),
        ("kernel_size", kernel_size),
        ("stride", stride),
        ("dilation", dilation),
    ):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(name + " must be a positive int")
        if value <= 0:
            raise ValueError(name + " must be a positive int")
    if isinstance(padding, bool) or not isinstance(padding, int):
        raise TypeError("padding must be a non-negative int")
    if padding < 0:
        raise ValueError("padding must be a non-negative int")
    H, W, K, S, P, D = height, width, kernel_size, stride, padding, dilation
    # self stores a H x W image and kernel a K x K filter, both in
    # row-major order. Dilation spaces the kernel taps by D, so the
    # effective receptive field spans E = D*(K-1)+1 positions.
    if len(x_data) != H * W:
        raise ValueError("conv2d input length must equal height * width")
    if len(k_data) != K * K:
        raise ValueError(
            "conv2d kernel length must equal kernel_size * kernel_size"
        )

def conv1d_batch(self, kernel, batch, channels, filters, length, size,
                 stride=1, padding=0, dilation=1, groups=1, bias=None):
    if not isinstance(kernel, Tensor):
        raise TypeError("kernel must be a Tensor")
    if bias is not None and not isinstance(bias, Tensor):
        raise TypeError("bias must be a Tensor or None")
    # The operands must hold non-empty 1D finite float lists; data may
    # have been mutated after construction, so re-validate at call time.
    x_data = _require_nonempty_float_vector(self, "conv1d_batch")
    w_data = _require_nonempty_float_vector(kernel, "conv1d_batch")
    b_data = None
    if bias is not None:
        b_data = _require_nonempty_float_vector(bias, "conv1d_batch")
    # batch, channels, filters, length, size, groups, stride and
    # dilation must be non-bool positive ints, and padding a non-bool
    # non-negative int.
    for name, value in (
        ("batch", batch),
        ("channels", channels),
        ("filters", filters),
        ("length", length),
        ("size", size),
        ("groups", groups),
        ("stride", stride),
        ("dilation", dilation),
    ):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(name + " must be a positive int")
        if value <= 0:
            raise ValueError(name + " must be a positive int")
    if isinstance(padding, bool) or not isinstance(padding, int):
        raise TypeError("padding must be a non-negative int")
    if padding < 0:
        raise ValueError("padding must be a non-negative int")
    B, C, O, N, K, G, S, P, D = (
        batch, channels, filters, length, size, groups, stride,
        padding, dilation,
    )
    # Groups partition the channels and filters into G disjoint blocks;
    # both counts must divide evenly for the split to be well defined.
    if C % G != 0 or O % G != 0:
        raise ValueError(
            "groups must evenly divide channels and filters"
        )
    CPG = C // G
    FPG = O // G
    # self stores B sequences of C channels of N samples and kernel O
    # filters of C/G channels of K weights, all in row-major order.
    if len(x_data) != B * C * N:
        raise ValueError(
            "conv1d_batch input length must equal "
            "batch * channels * length"
        )
    kernel_len = O * CPG * K
    if len(w_data) != kernel_len:
        if G == 1:
            raise ValueError(
                "conv1d_batch kernel length must equal "
                "filters * channels * size"
            )
        raise ValueError(
            "conv1d_batch kernel length must equal "
            "filters * (channels // groups) * size"
        )
    # The bias holds one trainable offset per output filter.
    if b_data is not None and len(b_data) != O:
        raise ValueError(
            "conv1d_batch bias length must equal filters"
        )
    # Dilation spaces the kernel taps by D, so the effective receptive
    # field spans E = D*(K-1)+1 positions.
    L = (N + 2 * P - D * (K - 1) - 1) // S + 1
    if L <= 0:
        raise ValueError("conv1d_batch output length must be positive")
    # Snapshot all operands at call time so later caller-side mutation
    # or replacement of any input can change neither the forward result
    # nor a pending backward pass.
    snapshot_x = list(x_data)
    snapshot_w = list(w_data)
    snapshot_b = list(b_data) if b_data is not None else None
    # Batched grouped multi-channel 1D cross-correlation: the kernel is
    # never flipped. Filter o belongs to group g = o // (O/G) and reads
    # only input channels c0 .. c0+C/G-1, where c0 = g*(C/G). The
    # output is B x O x L in row-major order; in ascending
    # (b, o, t, cl, r) order (cl the in-group channel, c = c0+cl) each
    # output starts at bias[o] (0.0 without a bias) and accumulates
    # y[(b*O+o)*L+t] += x[(b*C+c)*N+j] * w[(o*(C/G)+cl)*K+r],
    # with j = t*S+r*D-P; out-of-range input positions from padding
    # are skipped. With G=1 this reduces to dense (b, o, t, c, r)
    # order. A non-finite product or partial sum aborts before a result
    # tensor exists, so no state can change.
    out_len = B * O * L
    out_data = [0.0] * out_len
    for b in range(B):
        for o in range(O):
            g = o // FPG
            c0 = g * CPG
            bias_o = snapshot_b[o] if snapshot_b is not None else 0.0
            for t in range(L):
                oi = (b * O + o) * L + t
                acc = bias_o
                for cl in range(CPG):
                    c = c0 + cl
                    for r in range(K):
                        j = t * S + r * D - P
                        if not 0 <= j < N:
                            continue
                        xi = (b * C + c) * N + j
                        wi = (o * CPG + cl) * K + r
                        product = snapshot_x[xi] * snapshot_w[wi]
                        if not math.isfinite(product):
                            raise ValueError(
                                "conv1d_batch intermediate must be finite"
                            )
                        acc = acc + product
                        if not math.isfinite(acc):
                            raise ValueError(
                                "conv1d_batch intermediate must be finite"
                            )
                out_data[oi] = acc
    needs_grad = self.requires_grad or kernel.requires_grad
    if bias is not None and bias.requires_grad:
        needs_grad = True
    if not needs_grad:
        return Tensor._make(
            out_data, False, (), None,
            grad_validator=lambda g: _validate_vector_grad(g, out_len),
        )
    parent_self, parent_kernel = self, kernel
    parent_bias = bias

    def backward_fn(grad):
        # dx[xi] += g*w[wi] and dw[wi] += g*x[xi], accumulated from
        # 0.0 in the same ascending (b, o, t, cl, r) order, indexing
        # and group-channel mapping as the forward pass, with the same
        # dilated j computation and out-of-range skip; dw has no batch
        # index, so its contributions reduce across all B images.
        # db[o] += g reduces in ascending (b, t) order per filter. A
        # non-finite product or partial sum aborts the whole pass
        # before any grad is written.
        dx = [0.0] * (B * C * N)
        dw = [0.0] * (O * CPG * K)
        db = [0.0] * O if snapshot_b is not None else None
        for b in range(B):
            for o in range(O):
                g = o // FPG
                c0 = g * CPG
                for t in range(L):
                    gv = grad[(b * O + o) * L + t]
                    if db is not None:
                        db[o] = db[o] + gv
                        if not math.isfinite(db[o]):
                            raise ValueError(
                                "conv1d_batch backward "
                                "intermediate must be finite"
                            )
                    for cl in range(CPG):
                        c = c0 + cl
                        for r in range(K):
                            j = t * S + r * D - P
                            if not 0 <= j < N:
                                continue
                            xi = (b * C + c) * N + j
                            wi = (o * CPG + cl) * K + r
                            contrib_x = gv * snapshot_w[wi]
                            if not math.isfinite(contrib_x):
                                raise ValueError(
                                    "conv1d_batch backward "
                                    "intermediate must be finite"
                                )
                            dx[xi] = dx[xi] + contrib_x
                            if not math.isfinite(dx[xi]):
                                raise ValueError(
                                    "conv1d_batch backward "
                                    "intermediate must be finite"
                                )
                            contrib_w = gv * snapshot_x[xi]
                            if not math.isfinite(contrib_w):
                                raise ValueError(
                                    "conv1d_batch backward "
                                    "intermediate must be finite"
                                )
                            dw[wi] = dw[wi] + contrib_w
                            if not math.isfinite(dw[wi]):
                                raise ValueError(
                                    "conv1d_batch backward "
                                    "intermediate must be finite"
                                )
        # The same object may play several roles; merge such roles into
        # one contribution per tensor, and submit only parents that
        # require grad.
        merged = {}
        roles = [
            (parent_self, dx),
            (parent_kernel, dw),
        ]
        if parent_bias is not None:
            roles.append((parent_bias, db))
        for parent, value in roles:
            if not parent.requires_grad:
                continue
            entry = merged.get(id(parent))
            if entry is None:
                merged[id(parent)] = [parent, value]
            else:
                combined = _merge_grad(entry[1], value)
                _ensure_finite_grad(combined)
                entry[1] = combined
        return [(entry[0], entry[1]) for entry in merged.values()]

    parents = (parent_self, parent_kernel)
    if parent_bias is not None:
        parents = parents + (parent_bias,)
    return Tensor._make(
        out_data, True, parents, backward_fn,
        grad_validator=lambda g: _validate_vector_grad(g, out_len),
    )

def conv1d_multi(self, kernel, channels, filters, length, size,
                 stride=1, padding=0, dilation=1, bias=None,
                 padding_mode="zeros"):
    if not isinstance(kernel, Tensor):
        raise TypeError("kernel must be a Tensor")
    if bias is not None and not isinstance(bias, Tensor):
        raise TypeError("bias must be a Tensor or None")
    # The operands must hold non-empty 1D finite float lists; data may
    # have been mutated after construction, so re-validate at call time.
    x_data = _require_nonempty_float_vector(self, "conv1d_multi")
    w_data = _require_nonempty_float_vector(kernel, "conv1d_multi")
    b_data = None
    if bias is not None:
        b_data = _require_nonempty_float_vector(bias, "conv1d_multi")
    # channels, filters, length, size, stride and dilation must be
    # non-bool positive ints, and padding a non-bool non-negative int.
    for name, value in (
        ("channels", channels),
        ("filters", filters),
        ("length", length),
        ("size", size),
        ("stride", stride),
        ("dilation", dilation),
    ):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(name + " must be a positive int")
        if value <= 0:
            raise ValueError(name + " must be a positive int")
    if isinstance(padding, bool) or not isinstance(padding, int):
        raise TypeError("padding must be a non-negative int")
    if padding < 0:
        raise ValueError("padding must be a non-negative int")
    if not isinstance(padding_mode, str):
        raise TypeError("padding_mode must be a str")
    if padding_mode not in ("zeros", "reflect"):
        raise ValueError(
            "padding_mode must be 'zeros' or 'reflect'"
        )
    C, O, N, K, S, P, D = (
        channels, filters, length, size, stride, padding, dilation
    )
    # self stores C channels of N-length signals and kernel O filters of
    # C channels of K-length weights, all in row-major order.
    if len(x_data) != C * N:
        raise ValueError(
            "conv1d_multi input length must equal channels * length"
        )
    if len(w_data) != O * C * K:
        raise ValueError(
            "conv1d_multi kernel length must equal "
            "filters * channels * size"
        )
    # The bias holds one trainable offset per output filter.
    if b_data is not None and len(b_data) != O:
        raise ValueError(
            "conv1d_multi bias length must equal filters"
        )
    # Reflection padding folds back onto the signal at both edges, which
    # is only defined for a signal of at least two positions and a pad
    # width strictly smaller than that signal.
    if padding_mode == "reflect" and (N <= 1 or P >= N):
        raise ValueError(
            "conv1d_multi reflect padding requires length > 1 and "
            "padding < length"
        )
    # Dilation spaces the kernel taps by D, so the effective receptive
    # field spans E = D*(K-1)+1 positions; with D=1 this is simply K.
    E = D * (K - 1) + 1
    out_len = (N + 2 * P - E) // S + 1
    if out_len <= 0:
        raise ValueError("conv1d_multi output length must be positive")
    # Snapshot all operands at call time so later caller-side mutation
    # or replacement of any input can change neither the forward result
    # nor a pending backward pass.
    snapshot_x = list(x_data)
    snapshot_w = list(w_data)
    snapshot_b = list(b_data) if b_data is not None else None
    # Batched multi-channel 1D cross-correlation: the kernel is never
    # flipped. In ascending (o, t, c, r) order, each output starts at
    # bias[o] (0.0 without a bias) and accumulates
    # y[o*L+t] += x[c*N+j] * w[(o*C+c)*K+r],
    # with j = t*S+r*D-P. With zero padding, out-of-range input
    # positions from padding or the dilation gaps are skipped. With
    # reflection padding j is folded back into range first: j<0 maps
    # to -j, j>=N to 2*N-2-j. A non-finite product or partial sum
    # aborts before a result tensor exists, so no state can change.
    total_out = O * out_len
    out_data = [0.0] * total_out
    for o in range(O):
        bias_o = snapshot_b[o] if snapshot_b is not None else 0.0
        for t in range(out_len):
            oi = o * out_len + t
            out_data[oi] = bias_o
            for c in range(C):
                for r in range(K):
                    j = t * S + r * D - P
                    if padding_mode == "zeros":
                        if not 0 <= j < N:
                            continue
                    else:
                        if j < 0:
                            j = -j
                        if j >= N:
                            j = 2 * N - 2 - j
                    xi = c * N + j
                    wi = (o * C + c) * K + r
                    product = snapshot_x[xi] * snapshot_w[wi]
                    if not math.isfinite(product):
                        raise ValueError(
                            "conv1d_multi intermediate must be finite"
                        )
                    out_data[oi] = out_data[oi] + product
                    if not math.isfinite(out_data[oi]):
                        raise ValueError(
                            "conv1d_multi intermediate must be finite"
                        )
    needs_grad = self.requires_grad or kernel.requires_grad
    if bias is not None and bias.requires_grad:
        needs_grad = True
    if not needs_grad:
        return Tensor._make(out_data, False, (), None)
    parent_self, parent_kernel = self, kernel
    parent_bias = bias

    def backward_fn(grad):
        # dx[xi] += g*w[wi] and dw[wi] += g*x[xi], accumulated from
        # 0.0 in the same ascending (o, t, c, r) order as the forward
        # pass, using the same dilated j indexing, zero-padding skip
        # and reflection fold (several padded positions may fold onto
